/** Copies ABIs from the Foundry build into the services so they can never drift from the tested contracts. */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const read = (f: string) => JSON.parse(readFileSync(join(root, "contracts/out", f), "utf8")).abi;
const out = [
  "// Generated by tools/export-abi.ts. Do not edit.",
  `export const routerAbi = ${JSON.stringify(read("ExitRouter.sol/ExitRouter.json"))} as const;`,
  `export const alarmBookAbi = ${JSON.stringify(read("AlarmBook.sol/AlarmBook.json"))} as const;`,
  "",
].join("\n");
writeFileSync(join(root, "services/src/chain/abi.generated.ts"), out);
console.log("abi exported");
